<?php
namespace Database\Seeders;
use Illuminate\Database\Seeder; use Illuminate\Support\Facades\DB;
class PrivateWorkforceModuleSeeder extends Seeder { public function run(): void { $now=now(); foreach([['GEN','General / Unassigned'],['CLINIC','Clinical Services'],['NURSING','Nursing Services'],['LAB','Laboratory'],['PHARM','Pharmacy'],['ADMIN','Administration']] as [$code,$name]) DB::table('cost_centres')->updateOrInsert(['code'=>$code],['name'=>$name,'is_active'=>true,'created_at'=>$now,'updated_at'=>$now]); foreach([['attendance','minimum_rest_hours','Minimum rest hours between duties',['hours'=>8,'mode'=>'warning']],['overtime','require_approval','Overtime must be approved before payroll',['enabled'=>true]],['payroll','four_eye_review','Payroll requires prepare/check/approve separation',['enabled'=>true]],['contracts','expiry_warning_days','Contract expiry warning windows',['days'=>[90,60,30,7]]]] as [$m,$c,$l,$cfg]) DB::table('workforce_policy_rules')->updateOrInsert(['module'=>$m,'code'=>$c],['label'=>$l,'rule_config'=>json_encode($cfg),'is_active'=>true,'updated_at'=>$now,'created_at'=>$now]); }}
